function MigrationAgent(address _tokenContract) {
                if(msg.sender!=master)throw;
                MigrationAgent oldAgent = tokenContract;
                tokenContract = BlocklancerToken(_tokenContract);
                if (oldAgent.balance == 0) {
                    throw;
                }
                uint256 balance = oldAgent.balance;
                oldAgent.setBalance(msg.sender, balance);
                Transfer(oldAgent, tokenContract, balance);
                totalMigrated += balance;
            }
